namespace sv_ed3ecf18ae11449db7e34a5d25557965.Services;

/// <summary>
/// Scoped service that holds the current low-stock alert count and notifies
/// all subscribed components when new data arrives. Polling is managed by
/// the component that starts it (Dashboard), but the notification propagates
/// to every subscriber (sidebar badge, dashboard panel, etc.).
/// </summary>
public class InventoryAlertState : IDisposable
{
    private readonly InventoryAlertService _alertService;
    private readonly WarehouseState _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _pollingConsumers;

    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    public InventoryAlertState(InventoryAlertService alertService, WarehouseState warehouseState)
    {
        _alertService = alertService;
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Starts polling every 10 seconds. Multiple callers are ref-counted —
    /// polling stops only when all consumers call StopPolling.
    /// </summary>
    public void StartPolling()
    {
        _pollingConsumers++;
        if (_pollingConsumers == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void StopPolling()
    {
        _pollingConsumers = Math.Max(0, _pollingConsumers - 1);
        if (_pollingConsumers == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    /// <summary>
    /// Force an immediate refresh (e.g., after warehouse change).
    /// </summary>
    public async Task RefreshAsync()
    {
        LowStockCount = await _alertService.GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnChange?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                LowStockCount = await _alertService.GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
                OnChange?.Invoke();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async void OnWarehouseChanged()
    {
        if (_pollingConsumers > 0)
        {
            await RefreshAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

