@using sv_ed3ecf18ae11449db7e34a5d25557965.Services
@inject WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-0 text-white small">Current Warehouse</label>
    <select class="form-select form-select-sm" @onchange="OnWarehouseChanged" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var (id, name) in WarehouseState.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

@using sv_ed3ecf18ae11449db7e34a5d25557965.Services
@inject InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

@if (AlertState.LowStockCount > 0)
{
    <span class="badge bg-danger ms-2">@AlertState.LowStockCount</span>
}
else
{
    <span class="badge bg-success ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertState.OnChange += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertState.OnChange -= _handler;
        }
    }
}

