@using sv_ed3ecf18ae11449db7e34a5d25557965.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Currently Viewing: @GetWarehouseName()
        </h5>
        <p class="card-text text-muted">
            All data below is scoped to the selected warehouse. Switch warehouses using the dropdown in the top bar.
        </p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card text-bg-@(AlertState.LowStockCount > 5 ? "danger" : AlertState.LowStockCount > 0 ? "warning" : "success")">
            <div class="card-body text-center">
                <h2>@AlertState.LowStockCount</h2>
                <p class="mb-0">Low Stock Alerts</p>
                <small class="opacity-75">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h2>@WarehouseState.CurrentWarehouseId</h2>
                <p class="mb-0">Active Warehouse ID</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card text-bg-info">
            <div class="card-body text-center">
                <h2>@(_lastRefresh?.ToString("HH:mm:ss") ?? "—")</h2>
                <p class="mb-0">Last Refreshed</p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;
    private DateTime? _lastRefresh;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertState.OnChange += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when dashboard is visible
        AlertState.StartPolling();
    }

    private string GetWarehouseName()
    {
        return WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
            ?? WarehouseState.CurrentWarehouseId;
    }

    public void Dispose()
    {
        // Stop polling when leaving the page
        AlertState.StopPolling();

        if (_alertHandler is not null)
            AlertState.OnChange -= _alertHandler;
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }
}

